<?php
require_once __DIR__ . '/../config/app.php';
require_once __DIR__ . '/../includes/functions.php';
if (!isLoggedIn()) { redirect(SITE_URL . '/auth/login.php'); }
$room_id = isset($_GET['room_id']) ? (int) $_GET['room_id'] : (int) ($_SESSION['room_id'] ?? 0);
if (!$room_id) { redirect(SITE_URL . '/pages/dashboard.php'); }
$room = getRoomDetails($room_id);
if (!$room || ((int) $room['landlord_id'] !== (int) getCurrentUserId() && !isAdmin())) { redirect(SITE_URL . '/pages/dashboard.php'); }
$error=''; $success='';
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['upload'])) {
    if (!isset($_POST['csrf_token']) || !hash_equals($_SESSION['csrf_token'] ?? '', $_POST['csrf_token'])) { $error='Invalid security token'; }
    elseif (!empty($_FILES['images']['name'][0])) { $result=uploadRoomImages($room_id,getCurrentUserId(),$_FILES['images']); if (!empty($result['errors'])) { $error=implode('<br>',$result['errors']); } if (!empty($result['uploaded'])) { $success=$result['message']; $room=getRoomDetails($room_id);} }
    else { $error='No images selected'; }
}
if (isset($_POST['continue'])) { $redirect = $_SESSION['redirect_to'] ?? ('edit-listing.php?id=' . $room_id); unset($_SESSION['redirect_to'], $_SESSION['room_id']); redirect($redirect); }
$page_title='Upload Room Images'; require_once __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard-shell"><div class="dashboard-card" style="max-width:880px;"><div class="section-heading compact"><span class="section-kicker">Listing Media</span><h1>Upload Photos</h1><p class="muted-text">Add images for <strong><?php echo htmlspecialchars($room['title']); ?></strong>.</p></div><?php if($error): ?><div class="alert alert-error"><?php echo $error; ?></div><?php endif; ?><?php if($success): ?><div class="alert alert-success"><?php echo $success; ?></div><?php endif; ?><?php if(!empty($room['images'])): ?><div class="profile-card" style="padding:1.5rem;margin-bottom:1.5rem;"><h3 style="margin-bottom:1rem;">Current Photos (<?php echo count($room['images']); ?>/10)</h3><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:1rem;"><?php foreach($room['images'] as $image): ?><div style="position:relative;"><img src="<?php echo getRoomImageUrl($image['image_url']); ?>" style="width:100%;height:110px;object-fit:cover;border-radius:14px;border:<?php echo $image['is_primary']?'3px solid var(--primary)':'1px solid var(--border)'; ?>;"><?php if($image['is_primary']): ?><span style="position:absolute;top:6px;left:6px;background:var(--primary);color:white;padding:2px 8px;border-radius:999px;font-size:0.72rem;">Primary</span><?php endif; ?></div><?php endforeach; ?></div></div><?php endif; ?><form method="POST" enctype="multipart/form-data" class="profile-card" style="padding:1.5rem;margin-bottom:1rem;"><input type="hidden" name="csrf_token" value="<?php echo generateCSRFToken(); ?>"><div class="form-group"><label for="images">Select Images</label><input type="file" name="images[]" multiple accept="image/jpeg,image/png,image/webp" id="images" style="padding:1rem;border:2px dashed rgba(15,79,76,0.18);border-radius:16px;background:rgba(255,255,255,0.7);"><?php if(count($room['images'] ?? [])<10): ?><p class="muted-text">You can upload <?php echo 10-count($room['images'] ?? []); ?> more images.</p><?php else: ?><p class="muted-text">Maximum 10 images already uploaded.</p><?php endif; ?></div><div id="preview" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:1rem;margin-bottom:1.2rem;"></div><button type="submit" name="upload" class="btn-primary btn-block">Upload Images</button></form><form method="POST"><input type="hidden" name="csrf_token" value="<?php echo generateCSRFToken(); ?>"><button type="submit" name="continue" class="btn-outline btn-block">Continue to Edit Listing</button></form></div></section><script>document.getElementById('images')?.addEventListener('change',function(e){const preview=document.getElementById('preview');preview.innerHTML='';Array.from(e.target.files).forEach(file=>{if(!file.type.startsWith('image/'))return;const reader=new FileReader();reader.onload=function(evt){const div=document.createElement('div');div.innerHTML=`<img src="${evt.target.result}" style="width:100%;height:88px;object-fit:cover;border-radius:10px;">`;preview.appendChild(div);};reader.readAsDataURL(file);});});</script><?php require_once __DIR__ . '/../includes/footer.php'; ?>
